package edu.ankara.audiometer.domain.algorithm;
import edu.ankara.audiometer.domain.model.*;import java.util.*;
public final class HughsonWestlakeEngine { private HughsonWestlakeEngine(){}
 public static TestState presentTone(TestState s){ return s.withPresentation(AudiometryFunctions.createTonePresentation(s)).transition(s.currentEar(),s.currentFrequency(),s.currentIntensity(), s.direction()==PresentationDirection.INITIAL?TestPhase.DESCENDING_SEARCH:s.phase(), s.direction()); }
 public static TestState applyResponseToLastPresentation(TestState s, PatientResponse response){ TestState state=s.presentations().isEmpty()?presentTone(s):s; var list=new ArrayList<>(state.presentations()); var last=list.removeLast().withResponse(response); list.add(last); var withResponse=new TestState(state.session(),state.config(),state.currentEar(),state.currentFrequency(),state.currentIntensity(),state.phase(),state.direction(),list,state.eventHistory(),state.audiogram(),state.errors()); var decision=ThresholdDetector.detectThreshold(withResponse.presentations(),withResponse.config().algorithm()); if(decision.reached()){ var point=AudiometryFunctions.createAudiogramPoint(withResponse, decision.threshold().orElseThrow()); var withPoint=withResponse.withAudiogram(withResponse.audiogram().add(point, withResponse.config().allowRetest())); return advanceFrequencyOrEar(withPoint); }
 var next=AudiometryFunctions.nextIntensityAfterResponse(withResponse.currentIntensity(),response,withResponse.config().algorithm(),withResponse.config()); var dir=response.heard()?PresentationDirection.DESCENDING:PresentationDirection.ASCENDING; var phase=response.heard()?TestPhase.DESCENDING_SEARCH:TestPhase.ASCENDING_SEARCH; return withResponse.transition(withResponse.currentEar(),withResponse.currentFrequency(),next,phase,dir); }
 private static TestState advanceFrequencyOrEar(TestState s){ Optional<FrequencyHz> nf=AudiometryFunctions.nextFrequency(s.currentFrequency(),s.config().frequencyPlan()); if(nf.isPresent()) return s.transition(s.currentEar(),nf.get(),s.config().algorithm().startIntensity(),TestPhase.READY,PresentationDirection.INITIAL); Optional<Ear> ne=AudiometryFunctions.nextEar(s.currentEar(),s); if(ne.isPresent()) return s.transition(ne.get(),s.config().frequencyPlan().activeOrder().getFirst(),s.config().algorithm().startIntensity(),TestPhase.READY,PresentationDirection.INITIAL); return s.transition(s.currentEar(),s.currentFrequency(),s.currentIntensity(),TestPhase.COMPLETED,s.direction()); }
}
